        $s1 = "beacon" wide ascii
        $s2 = { 60 00 6D 00 73 00 68 00 65 00 6C 00 6C 00 } // "mshtml"
        $s3 = { 48 8B C4 48 89 58 10 48 89 68 18 } // common shellcode stub
    condition:
        uint16(0) == 0x5A4D and (filesize < 1MB) and (entropy(0, filesize) > 7.5) and any of ($s*)
}

